commands:
TODAY=$(date +%Y-%m-%d)
YEST=$(date -d "yesterday" +%Y-%m-%d)
mkdir -p /tmp/log_report
MATCHFILE=/tmp/log_report/matches.txt
SUMMARY=/tmp/log_report/summary.txt
>"$MATCHFILE"
# Gather lines containing today's or yesterday's date from all files under /work/logs
if [ -d /work/logs ]; then
  grep -HinE "$TODAY|$YEST" /work/logs/* > "$MATCHFILE" 2>/dev/null || true
fi
# Basic summary
{
  echo "Log files in /work/logs/:";
  ls -la /work/logs/ 2>/dev/null || true;
  echo;
  echo "Matched lines for $YEST and $TODAY (file:line:content) saved to $MATCHFILE";
  echo;
  echo "Match counts per file:";
  if [ -s "$MATCHFILE" ]; then
    awk -F: '{print $1}' "$MATCHFILE" | sort | uniq -c | sort -nr;
  else
    echo "(no matched lines)";
  fi
  echo;
  echo "Error keyword counts (in matched lines):";
  if [ -s "$MATCHFILE" ]; then
    grep -iE "error|warn|warning|exception|traceback|fail|failed|fatal" "$MATCHFILE" | sed -E 's/.*:([0-9]+):(.*)$/\2/' | awk '{print tolower($0)}' | sed -E 's/.*(error|warn|warning|exception|traceback|fail|failed|fatal).*/\1/' | sort | uniq -c | sort -nr;
  else
    echo "(no matched lines)";
  fi
  echo;
  echo "Top 20 frequent messages (matched lines normalized):";
  if [ -s "$MATCHFILE" ]; then
    grep -iE "error|warn|warning|exception|traceback|fail|failed|fatal" "$MATCHFILE" | sed -E 's/^([^:]+):([0-9]+):(.*)$/\3/' | sed 's/^[[:space:]]*//' | sort | uniq -c | sort -nr | head -n 20;
  else
    echo "(no matched lines)";
  fi
  echo;
  echo "Timestamps sample (first 200 matched lines):";
  if [ -s "$MATCHFILE" ]; then
    awk -F: '{ if (NF>=3) print $1 ":" $2 ": " $3; else print $0 }' "$MATCHFILE" | head -n 200;
  else
    echo "(no matched lines)";
  fi
} > "$SUMMARY"
# Create a human-readable report.md using the summary. Keep it concise.
{
  echo "Log Error Report";
  echo "";
  echo "Scope: lines containing dates $YEST and $TODAY in /work/logs/";
  echo "";
  if [ -s "$MATCHFILE" ]; then
    echo "Summary (see /tmp/log_report/summary.txt for full details):";
    echo "";
    # Extract top keywords counts
    grep -iE "error|warn|warning|exception|traceback|fail|failed|fatal" "$MATCHFILE" | sed -E 's/.*:([0-9]+):(.*)$/\2/' | awk '{print tolower($0)}' | sed -E 's/.*(error|warn|warning|exception|traceback|fail|failed|fatal).*/\1/' | sort | uniq -c | sort -nr | awk '{print "- " $2 ": " $1 " occurrences"}' | head -n 20
    echo "";
    echo "Top messages (approximate, up to 10):";
    grep -iE "error|warn|warning|exception|traceback|fail|failed|fatal" "$MATCHFILE" | sed -E 's/^([^:]+):([0-9]+):(.*)$/\3/' | sed 's/^[[:space:]]*//' | sort | uniq -c | sort -nr | head -n 10 | awk '{ $1=""; sub(/^ +/,""); print "- " $0 }'
    echo "";
    echo "Files with most matched entries:";
    awk -F: '{print $1}' "$MATCHFILE" | sort | uniq -c | sort -nr | head -n 10 | awk '{print "- " $2 ": " $1 " matches"}'
    echo "";
    echo "For full extracted matches and timestamp samples, see /tmp/log_report/summary.txt";
  else
    echo "No log lines containing dates $YEST or $TODAY were found in /work/logs/.";
  fi
} > /work/report.md
# Also copy the full summary for inspection
cp "$SUMMARY" /tmp/log_report/summary.txt 2>/dev/null || true
# Output the summary to stdout for the evaluation harness
cat "$SUMMARY" || true
# exit
exit 0
